264	        uart_putstr(nd_type_name(nd_type[n]));
265	    }
266	    if (nd_kind[n] == NODE_DCL) {
267	        if (nd_stor[n] == STOR_STATIC) uart_putstr(" STATIC");
268	        if (nd_stor[n] == STOR_EXTERNAL) uart_putstr(" EXTERNAL");
269	        if (nd_level[n] > 0) {
