280	        if (nd_ival[n] & 1) uart_putstr(" FREESTANDING");
281	        if (nd_ival[n] & 2) uart_putstr(" NAKED");
282	        if (nd_ival[n] & 4) uart_putstr(" LEAF");
283	        /* nd_stor stores return type */
284	        if (nd_stor[n] != TYPE_NONE) {
285	            uart_putstr(" returns=");
286	            uart_putstr(nd_type_name(nd_stor[n]));
287	        }
288	    }
289	    uart_putchar(10);
290	}
