292	/* Recursively dump a tree */
293	void nd_dump(int n, int depth) {
294	    int d;
295	    int p;
296	    if (n == NODE_NULL) return;
297	    nd_print(n, depth);
298	    /* PROC: dump params then body with labels */
299	    if (nd_kind[n] == NODE_PROC) {
300	        /* Dump parameter list */
301	        p = nd_left[n];
302	        if (p != NODE_NULL) {
303	            d = 0;
304	            while (d < depth + 1) { uart_putstr("  "); d = d + 1; }
305	            uart_puts("(PARAMS)");
306	            while (p != NODE_NULL) {
307	                nd_print(p, depth + 2);
308	                p = nd_next[p];
309	            }
310	        }
311	        /* Dump body */
312	        if (nd_right[n] != NODE_NULL) {
313	            d = 0;
314	            while (d < depth + 1) { uart_putstr("  "); d = d + 1; }
315	            uart_puts("(BODY)");
316	            nd_dump(nd_right[n], depth + 2);
317	        }
318	        nd_dump(nd_next[n], depth);
319	        return;
320	    }
321	    nd_dump(nd_left[n], depth + 1);
322	    nd_dump(nd_right[n], depth + 1);
323	    /* IF: dump else branch stored in nd_ival */
324	    if (nd_kind[n] == NODE_IF && nd_ival[n] != NODE_NULL) {
325	        d = 0;
326	        while (d < depth + 1) { uart_putstr("  "); d = d + 1; }
327	        uart_puts("(ELSE)");
328	        nd_dump(nd_ival[n], depth + 1);
329	    }
330	    /* DO_COUNT: dump end expression stored in nd_ival */
331	    if (nd_kind[n] == NODE_DO_COUNT && nd_ival[n] != NODE_NULL) {
332	        d = 0;
333	        while (d < depth + 1) { uart_putstr("  "); d = d + 1; }
334	        uart_puts("(TO)");
335	        nd_dump(nd_ival[n], depth + 1);
336	    }
337	    /* SELECT: dump WHEN children via nd_left sibling chain,
338	       OTHERWISE body stored in nd_ival */
339	    if (nd_kind[n] == NODE_SELECT) {
340	        if (nd_ival[n] != NODE_NULL) {
341	            d = 0;
342	            while (d < depth + 1) { uart_putstr("  "); d = d + 1; }
343	            uart_puts("(OTHERWISE)");
344	            nd_dump(nd_ival[n], depth + 1);
345	        }
346	        nd_dump(nd_next[n], depth);
347	        return;
348	    }
349	    nd_dump(nd_next[n], depth);
350	}
351	
352	#endif
