1	/* ast.h -- AST node types and pool for PL/SW compiler */
2	/* Uses parallel arrays instead of structs (tc24r workaround) */
3	
4	#ifndef AST_H
5	#define AST_H
6	
7	#include "arena.h"
8	
9	/* Node kind constants */
10	#define NODE_NONE          0
11	#define NODE_PROGRAM       1
12	#define NODE_DCL           2
13	#define NODE_PROC          3
14	#define NODE_IF            4
15	#define NODE_DO_WHILE      5
16	#define NODE_DO_COUNT      6
17	#define NODE_ASSIGN        7
18	#define NODE_BINOP         8
19	#define NODE_UNOP          9
20	#define NODE_CALL         10
21	#define NODE_RETURN       11
22	#define NODE_LITERAL      12
23	#define NODE_IDENT        13
24	#define NODE_ASM_BLOCK    14
25	#define NODE_FIELD_ACCESS 15
26	#define NODE_ARRAY_ACCESS 16
27	#define NODE_ADDR         17
28	#define NODE_DEREF        18
29	#define NODE_BLOCK        19
30	#define NODE_PARAM        20
31	#define NODE_SELECT       21
32	
33	/* Type info constants */
34	#define TYPE_NONE    0
35	#define TYPE_INT8    1
36	#define TYPE_INT16   2
37	#define TYPE_INT24   3
38	#define TYPE_BYTE    4
39	#define TYPE_CHAR    5
40	#define TYPE_BIT     6
41	#define TYPE_WORD    7
42	#define TYPE_PTR     8
43	#define TYPE_ARRAY   9
44	#define TYPE_RECORD  10
45	
46	/* Storage class constants */
47	#define STOR_AUTO     0
48	#define STOR_STATIC   1
49	#define STOR_EXTERNAL 2
50	#define STOR_BASED    3
51	
52	/* Null node index sentinel */
53	#define NODE_NULL (-1)
54	
55	/* Node pool -- parallel arrays, accessed via macros below.
56	   The _arr backing arrays are an implementation detail; callers use
57	   the nd_kind(i) / nd_type(i) / ... accessor form so storage can move
58	   to chunk-backed allocation without touching ~391 callsites. */
59	#define NODE_POOL_MAX 12288
60	
61	int nd_kind_arr[NODE_POOL_MAX];   /* node kind */
62	int nd_type_arr[NODE_POOL_MAX];   /* type info */
63	int nd_stor_arr[NODE_POOL_MAX];   /* storage class */
64	int nd_level_arr[NODE_POOL_MAX];  /* DCL level (1,3,5,...) */
65	int nd_left_arr[NODE_POOL_MAX];   /* left child index */
66	int nd_right_arr[NODE_POOL_MAX];  /* right child index */
67	int nd_next_arr[NODE_POOL_MAX];   /* sibling/next index */
68	int nd_ival_arr[NODE_POOL_MAX];   /* integer value or operator */
69	int nd_line_arr[NODE_POOL_MAX];   /* source line number (1-based) */
70	char *nd_name_arr[NODE_POOL_MAX]; /* name (arena-allocated) */
71	
72	#define nd_kind(i)  (nd_kind_arr[(i)])
73	#define nd_type(i)  (nd_type_arr[(i)])
74	#define nd_stor(i)  (nd_stor_arr[(i)])
75	#define nd_level(i) (nd_level_arr[(i)])
76	#define nd_left(i)  (nd_left_arr[(i)])
77	#define nd_right(i) (nd_right_arr[(i)])
78	#define nd_next(i)  (nd_next_arr[(i)])
79	#define nd_ival(i)  (nd_ival_arr[(i)])
80	#define nd_line(i)  (nd_line_arr[(i)])
81	#define nd_name(i)  (nd_name_arr[(i)])
82	
83	int nd_count;                     /* number of allocated nodes */
84	
85	void ast_init(void) {
86	    nd_count = 0;
87	    ast_pool_exhausted = 0;
88	}
89	
90	/* Allocate a new node. Returns node index or NODE_NULL on OOM. */
91	int ast_pool_exhausted;
92	
93	int nd_alloc(int kind) {
94	    if (nd_count >= NODE_POOL_MAX) {
95	        if (!ast_pool_exhausted) {
96	            ast_pool_exhausted = 1;
97	            uart_puts("ERROR: AST node pool exhausted (12288 nodes)");
98	            uart_puts("Program too large for single compilation unit.");
99	        }
100	        return NODE_NULL;
101	    }
102	    int i = nd_count;
103	    nd_count = nd_count + 1;
104	    nd_kind(i)  = kind;
105	    nd_type(i)  = TYPE_NONE;
106	    nd_stor(i)  = STOR_AUTO;
107	    nd_level(i) = 0;
108	    nd_left(i)  = NODE_NULL;
109	    nd_right(i) = NODE_NULL;
110	    nd_next(i)  = NODE_NULL;
111	    nd_ival(i)  = 0;
112	    nd_line(i)  = lex_line;
113	    nd_name(i)  = 0;
114	    return i;
115	}
116	
117	/* Set the name on a node (copies string into arena) */
118	void nd_set_name(int n, char *name) {
119	    if (n < 0 || n >= nd_count) return;
120	    int len = str_len(name);
121	    char *s = arena_alloc(len + 1);
122	    if (s) {
123	        str_copy(s, name);
124	        nd_name(n) = s;
125	    }
126	}
127	
128	/* Append child to end of a node's sibling chain via nd_next */
129	void nd_append(int parent, int child) {
130	    if (parent < 0 || child < 0) return;
131	    /* Find the appropriate child slot */
132	    if (nd_left(parent) == NODE_NULL) {
133	        nd_left(parent) = child;
134	        return;
135	    }
136	    /* Walk the sibling chain from left child */
137	    int cur = nd_left(parent);
138	    while (nd_next(cur) != NODE_NULL) {
139	        cur = nd_next(cur);
140	    }
141	    nd_next(cur) = child;
142	}
143	
144	/* Create a literal node */
145	int nd_literal(int value) {
146	    int n = nd_alloc(NODE_LITERAL);
147	    if (n != NODE_NULL) {
148	        nd_ival(n) = value;
149	        nd_type(n) = TYPE_INT24;
150	    }
151	    return n;
152	}
153	
154	/* Create an identifier node */
155	int nd_ident(char *name) {
156	    int n = nd_alloc(NODE_IDENT);
157	    if (n != NODE_NULL) {
158	        nd_set_name(n, name);
159	    }
160	    return n;
161	}
162	
163	/* Create a binary operator node */
164	int nd_binop(int op, int left, int right) {
165	    int n = nd_alloc(NODE_BINOP);
166	    if (n != NODE_NULL) {
167	        nd_ival(n) = op;
168	        nd_left(n) = left;
169	        nd_right(n) = right;
170	    }
171	    return n;
172	}
173	
174	/* Create a unary operator node */
175	int nd_unop(int op, int operand) {
176	    int n = nd_alloc(NODE_UNOP);
177	    if (n != NODE_NULL) {
178	        nd_ival(n) = op;
179	        nd_left(n) = operand;
180	    }
181	    return n;
182	}
183	
184	/* Create an assignment node */
185	int nd_assign(int target, int value) {
186	    int n = nd_alloc(NODE_ASSIGN);
187	    if (n != NODE_NULL) {
188	        nd_left(n) = target;
189	        nd_right(n) = value;
190	    }
191	    return n;
192	}
193	
194	/* Create a CALL node */
195	int nd_call(char *name, int args) {
196	    int n = nd_alloc(NODE_CALL);
197	    if (n != NODE_NULL) {
198	        nd_set_name(n, name);
199	        nd_left(n) = args;
200	    }
201	    return n;
202	}
203	
204	/* Create a RETURN node */
205	int nd_return(int expr) {
206	    int n = nd_alloc(NODE_RETURN);
207	    if (n != NODE_NULL) {
208	        nd_left(n) = expr;
209	    }
210	    return n;
211	}
212	
