int main() {
    char line[LINE_MAX];
    int suite;
    int len;

    uart_puts("PL/SW Compiler Tests v0.1");
    uart_puts("COR24 target");
    uart_putstr("Enter suite # (0-37) or 'a' for all: ");

    len = uart_getline(line, LINE_MAX);

    if (len > 0 && (line[0] == 65 || line[0] == 97)) {
        /* 'A' or 'a' -- run all suites */
        suite = 0;
        while (suite < SUITE_COUNT) {
            run_suite(suite);
            suite = suite + 1;
        }
    } else if (len > 0) {
        /* Parse suite number */
        suite = 0;
        int i = 0;
        while (i < len && line[i] >= 48 && line[i] <= 57) {
            suite = suite * 10 + (line[i] - 48);
            i = i + 1;
        }
        if (!run_suite(suite)) {
            uart_putstr("Unknown suite: ");
            print_int(suite);
            uart_putchar(10);
        }
    }

    return 0;
}

