13	/* COR24 runtime preamble: _start entry point */
14	void emit_runtime_start(void) {
15	    emit_line("        .text");
16	    emit_nl();
17	    emit_line("        .globl  _start");
18	    emit_line("_start:");
19	    emit_line("        la      r0,_MAIN");
20	    emit_line("        jal     r1,(r0)");
21	    emit_line("_halt:");
22	    emit_line("        bra     _halt");
