26	/* COR24 UART_PUTCHAR runtime: write byte to UART */
27	void emit_runtime_uart_putchar(void) {
28	    emit_line("        .globl  _UART_PUTCHAR");
29	    emit_line("_UART_PUTCHAR:");
30	    emit_line("        push    fp");
31	    emit_line("        push    r2");
32	    emit_line("        push    r1");
33	    emit_line("        mov     fp,sp");
34	    /* Busy-wait: poll TX busy (bit 7 of status at 0xFF0101) */
35	    emit_line("_uart_tx_wait:");
36	    emit_line("        la      r2,16711937");
37	    emit_line("        lbu     r0,0(r2)");
38	    emit_line("        lcu     r1,128");
39	    emit_line("        and     r0,r1");
40	    emit_line("        ceq     r0,z");
41	    emit_line("        brf     _uart_tx_wait");
42	    /* Write byte to UART data register (0xFF0100) */
43	    emit_line("        la      r2,16711936");
44	    emit_line("        lw      r0,9(fp)");
45	    emit_line("        sb      r0,0(r2)");
46	    emit_line("        mov     sp,fp");
47	    emit_line("        pop     r1");
48	    emit_line("        pop     r2");
49	    emit_line("        pop     fp");
50	    emit_line("        jmp     (r1)");
51	    emit_nl();
52	}
