119	/* Compile a PL/SW source string to a complete .s program.
120	 * Returns the assembly output string, or 0 on error. */
121	char *compile_program(char *source) {
122	    int prog;
123	
124	    /* Initialize all subsystems */
125	    arena_init();
126	    ast_init();
127	    sym_init();
128	    types_init();
129	    layout_init();
130	    emit_init();
131	    cg_init();
132	    cg_static_init();
133	    mac_init();
134	
135	    /* Build source line table for listing */
136	    src_lines_init(source, str_len(source));
137	
138	    /* Parse */
139	    parse_init(source);
140	    prog = parse_program();
141	    if (parse_err) {
142	        return 0;
143	    }
144	    if (lex_fatal) {
145	        return 0;
146	    }
147	
148	    /* Check for %DEFINE NOLISTING */
149	    if (def_defined("NOLISTING")) {
150	        cg_listing = 0;
151	    }
152	
153	    /* Layout globals */
154	    layout_globals(prog);
155	    if (layout_err) {
156	        uart_putstr("STORAGE ERROR: ");
157	        uart_puts(layout_errmsg);
158	        return 0;
159	    }
160	
161	    /* Emit runtime preamble (suppressed by %DEFINE LIBRARY) */
162	    if (!def_defined("LIBRARY")) {
163	        emit_runtime_start();
164	        emit_runtime_uart_putchar();
165	        emit_runtime_uart_getchar();
166	        emit_runtime_uart_puts();
167	    }
168	
169	    /* Emit user procedures */
170	    cg_program_procs(prog);
171	    if (cg_err) {
172	        return 0;
173	    }
174	
175	    /* Emit software division routine if any procedure used '/'.
176	     * Suppressed in LIBRARY mode -- library modules reference __plsw_div
177	     * as an external symbol resolved by the linker from the entry module. */
178	    if (!def_defined("LIBRARY")) {
179	        cg_emit_div_routine();
180	    }
181	
182	    /* Emit static data */
183	    cg_emit_static_data(prog);
184	
185	    /* Emit string literal table */
186	    cg_emit_string_table();
187	
188	    /* Drain the streaming buffer's tail to UART. Bytes prior
189	     * to this already flowed during emit_char's auto-flush;
190	     * this just pushes whatever's left in emit_buf. Callers in
191	     * production (main()'s compile-mode handler) must NOT then
192	     * print emit_output() -- the streaming has already done
193	     * the work, and printing the tail again would duplicate
194	     * the last < 4 KB. emit_output() is still returned so
195	     * compile_program keeps its NULL-on-failure /
196	     * non-NULL-on-success contract, and so test suites that
197	     * inspect short emissions via str_find continue to work
198	     * for fragments that fit in the unflushed tail. */
199	    emit_flush();
200	    return emit_output();
201	}
202	
203	#endif /* COMPILE_H */

